listCss:
.nav > li > a {padding-left:15px;padding-right:15px;}
#news-container {
	background-color:#f4f2f0;
	}
.news-txt h2 {
	color:#002d49;
	font-weight:bold;
	text-align:center;
	}
.news-txt p {
	color:#0088d1;
	font-size:18px;
	line-height:30px;
	}
.news-txt-b {
	font-weight:bold;
	text-align:center;
	}
.page_spacing {
	padding-top:50px;
	padding-bottom:50px;
}
.page_spacing-2 {
	padding-top:30px;
	padding-bottom:30px;
}
.news-h4 {
	color:#1eb9ee;
	font-weight:bold;
	font-style:italic;
	}
.news-item {
	/*border-bottom:2px solid #53c7ee;*/
	padding:30px 0 0 0;
	}
.news-item-more {
	border-bottom:2px solid #53c7ee;
	padding:5px 0 5px 0;
	}
.news-time-style-1 {
	color:#666;
	font-size:18px;
	font-style:italic;
	}
.news-img-border {
	border-bottom:8px solid #0086cd;
	}
.news-title-style {
	padding:30px 0 0 0;
	color:#0088d1;
	font-weight:bold;
	font-size:18px;
	}
.news-text{
	font-size:16px;
	}
.news-right-list {
	padding:30px 0 30px 0;
	}
.news-right-list-title {
	color:#0088d1;
	font-weight:bold;
	font-size:18px;
	font-style:italic;
	}
